package ru.neverland.townydiplomacy;

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import org.bukkit.configuration.file.YamlConfiguration;
import ru.neverland.core.*;
import ru.neverland.townydiplomacy.aid.*;

public final class AidSmoke {
    static int checks;static final UUID A=UUID.randomUUID(),B=UUID.randomUUID(),E=UUID.randomUUID(),WORLD=UUID.randomUUID(),P=UUID.randomUUID(),V=UUID.randomUUID();static final long NOW=1_000_000;
    static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
    interface Work{void run()throws Exception;}static void denied(Work action,String why)throws Exception{try{action.run();}catch(Exception good){check(true,why);return;}throw new AssertionError(why);}
    static <T>T done(CompletionStage<T> stage)throws Exception{return stage.toCompletableFuture().get(5,TimeUnit.SECONDS);}
    static AidFact fact(UUID actorTown,UUID victimTown,UUID territory,long at,long damage){return new AidFact(UUID.randomUUID(),at,P,actorTown,V,victimTown,territory,damage,WORLD,-8,80,-17);}
    static AidPact pact(){return new AidPact(UUID.randomUUID(),UUID.randomUUID(),A,B,UUID.randomUUID(),UUID.randomUUID(),"first","second",NOW,NOW+1000,NOW+86_400_000,60_000,20_000,AidPact.Phase.ACTIVE,"Signed political aid");}
    public static void main(String[] args)throws Exception{
        var p=pact();var initial=new AidState(Map.of(p.id(),p),Map.of(),List.of());var eligible=Set.of(p.id());var attack=fact(E,B,B,NOW+2000,2000);
        var state=initial.observe(attack,eligible);check(state.calls().size()==1,"real enemy attack on beneficiary land opens one call");var call=state.calls().values().iterator().next();check(call.helper().equals(A)&&call.beneficiary().equals(B)&&call.enemy().equals(E)&&call.attack().equals(attack),"exact parties, original attack player IDs and location preserved");
        check(state.observe(attack,eligible).equals(state),"attack replay cannot create another call");check(initial.observe(fact(E,B,A,NOW+2000,2000),eligible).equals(initial),"outside-city attack cannot demand aid");check(initial.observe(attack,Set.of()).equals(initial),"unavailable alliance never creates obligation");
        check(call.observe(fact(A,E,A,NOW+3000,5000)).equals(call),"help outside protected territory not accepted");check(call.observe(fact(B,E,B,NOW+3000,5000)).equals(call),"own-city action is not allied help");check(call.observe(fact(A,B,B,NOW+3000,5000)).equals(call),"wrong enemy cannot fulfill assistance");check(call.observe(fact(A,E,B,call.deadline(),5000)).equals(call),"deadline is strict");
        var hit=fact(A,E,B,NOW+3000,5000);var partial=call.observe(hit);check(partial.confirmedMilliDamage()==5000&&partial.status()==AidCall.Status.OPEN,"only verified final damage advances partial aid");check(partial.observe(hit).equals(partial),"proof UUID replay is idempotent");check(partial.observe(fact(A,E,B,NOW+4000,5000)).equals(partial),"same player pair has five second evidence throttle");
        var completed=partial.observe(fact(A,E,B,NOW+9000,15_000));check(completed.status()==AidCall.Status.FULFILLED&&completed.confirmedMilliDamage()==20_000,"enough facts fulfill exactly the agreed target");check(completed.observe(fact(A,E,B,NOW+20_000,20_000)).equals(completed),"fulfilled call cannot accumulate more credit");
        var partialState=new AidState(initial.pacts(),Map.of(call.id(),partial),List.of());check(partialState.expire(call.deadline(),eligible).calls().get(call.id()).status()==AidCall.Status.UNANSWERED,"observed timeout is informational only");var neutral=partialState.expire(call.deadline(),Set.of()).calls().get(call.id());check(neutral.status()==AidCall.Status.UNASSESSED&&neutral.proof().equals(partial.proof()),"provider outage neutralizes deadline and retains proof");check(partialState.neutral("Pause").calls().get(call.id()).status()==AidCall.Status.UNASSESSED,"administrative pause never counts as missed help");
        denied(()->new AidFact(UUID.randomUUID(),NOW,P,A,V,E,B,0,WORLD,0,0,0),"zero damage rejected");denied(()->new AidFact(UUID.randomUUID(),NOW,P,A,V,E,B,20_001,WORLD,0,0,0),"overkill evidence capped to player health range");denied(()->new AidCall(call.id(),p.id(),B,A,E,call.opened(),call.deadline(),20_000,AidCall.Status.FULFILLED,"fake",attack,List.of(hit)),"no button or forged status substitutes for missing evidence");
        check(AidSettings.load(new YamlConfiguration()).equals(new AidSettings(true,30,30,20)),"existing config gains safe optional defaults");var bad=new YamlConfiguration();bad.set("mutual-aid.enabled","yes");denied(()->AidSettings.load(bad),"bad optional switch is rejected explicitly");
        Path dir=Files.createTempDirectory("diplomacy-aid-"),file=dir.resolve("mutual-aid.yml"),old=dir.resolve("diplomacy.yml");Files.writeString(old,"original treaty registry untouched");var repo=new AidRepository(file);done(repo.load());done(repo.commit(repo.state(),partialState));check(repo.state().equals(partialState),"ACK publishes immutable journal");
        var field=AtomicFiles.class.getDeclaredField("writers");field.setAccessible(true);@SuppressWarnings("unchecked")var locks=(Map<Path,ReentrantLock>)field.get(null);var lock=locks.computeIfAbsent(file.toAbsolutePath().normalize(),k->new ReentrantLock());var next=new AidState(initial.pacts(),Map.of(call.id(),completed),List.of());CompletionStage<?> pending;CompletionStage<Void> closing;
        lock.lock();try{pending=repo.commit(partialState,next);Thread.sleep(25);check(repo.busy()&&!pending.toCompletableFuture().isDone()&&repo.state().equals(partialState),"blocked physical write cannot publish unacknowledged aid");check(SuiteState.tryRun("aid delayed writer",()->{}),"aid disk wait never owns shared lock");denied(()->done(repo.commit(partialState,next)),"concurrent decisions cannot race one ACK");closing=repo.closeAsync();check(!closing.toCompletableFuture().isDone(),"shutdown drains accepted write");}finally{lock.unlock();}
        done(pending);done(closing);var restarted=new AidRepository(file);check(done(restarted.load()).equals(next),"restart restores exact agreement and all proof UUIDs");check(Files.readString(old).equals("original treaty registry untouched"),"optional journal never rewrites existing diplomacy");done(restarted.closeAsync());
        Files.writeString(file,"schema: 1\npacts: [invalid\n");String corrupt=Files.readString(file);var broken=new AidRepository(file);denied(()->done(broken.load()),"bad optional data refuses load");check(Files.readString(file).equals(corrupt)&&Files.readString(old).equals("original treaty registry untouched"),"corrupt optional source and legacy registry retained");done(broken.closeAsync());
        Path blocked=dir.resolve("blocked");var failing=new AidRepository(blocked);done(failing.load());Files.createDirectory(blocked);Files.writeString(blocked.resolve("original"),"keep");denied(()->done(failing.commit(failing.state(),partialState)),"actual filesystem refusal never publishes unconfirmed assistance");check(!failing.writable()&&failing.state().equals(AidState.empty())&&Files.readString(blocked.resolve("original")).equals("keep"),"failed writer closes mutations and preserves original data");done(failing.closeAsync());
        Files.writeString(file,AidRepository.encode(next));var missing=YamlConfiguration.loadConfiguration(file.toFile());missing.set("calls."+call.id()+".attack.x",null);Files.writeString(file,missing.saveToString());denied(()->AidRepository.read(file),"missing evidence coordinate cannot silently become zero");
        System.out.println("AidSmoke PASS "+checks+" checks");
    }
}
